CREATE TABLE cliente (
  id_cliente INT PRIMARY KEY,
  nombre     VARCHAR(50),
  correo     VARCHAR(80)
);

CREATE TABLE pedido (
  id_pedido  INT PRIMARY KEY,
  fecha      DATE,
  id_cliente INT REFERENCES cliente(id_cliente)
);

