CREATE TABLE usuarios (
  id     INT PRIMARY KEY,
  nombre VARCHAR(50),
  edad   INT,
  ciudad VARCHAR(50)
);

SELECT nombre, edad
FROM usuarios
WHERE ciudad = 'Guatemala';

UPDATE usuarios
SET edad = 23
WHERE id = 1;

